/// <summary>
/// MPJ_6030_VendorInvoiceDocument
/// </summary>
[ExtensionOf(classStr(VendInvoiceDocumentDP))]
public final class METVendInvoiceDocumentDP_Extension
{
    public Notes       metHeaderNotes;

}

Method.Source:
    /// <summary>
    ///     Populates values into the <c>VendInvoiceDocumentTmp</c> table.
    /// </summary>
    /// <param name="_purchInvoiceTransOrTaxTrans">
    ///     A value that indicates whether it is transaction details or tax details.
    /// </param>
    ///     <param name="_vendPaymSched">
    ///     The <c>vendPaymSched</c> variable.
    /// </param>
    protected void populateVendInvoiceDocumentTmp(NoYes _purchInvoiceTransOrTaxTrans, NoYes _vendPaymSched)
    {
        VendTable       metInvoiceAccount = vendInvoiceJour.vendTable_InvoiceAccount();
        next populateVendInvoiceDocumentTmp(_purchInvoiceTransOrTaxTrans, _vendPaymSched);

        vendInvoiceDocumentTmp.METKnownAs = DirPartyTable::findRec(metInvoiceAccount.Party).KnownAs;
        vendInvoiceDocumentTmp.METVendAccount = metInvoiceAccount.AccountNum;
        vendInvoiceDocumentTmp.VendName = metInvoiceAccount.name();

        this.metSetDocumentNote();
    }

    /// <summary>
    /// Set document note
    /// </summary>
    public void metSetDocumentNote()
    {

        LedgerJournalTrans  metLedgerJournalTrans;

        if (!metHeaderNotes)
        {
            vendInvoiceDocumentTmp.METHeaderNotes =  this.metGetDocuRef(VendInvoiceInfoTable::findFromVendInvoiceJour(vendInvoiceJour.PurchId,
                                                                                                                      vendInvoiceJour.InvoiceId,
                                                                                                                      vendInvoiceJour.ParmId));
            if (!vendInvoiceDocumentTmp.METHeaderNotes)
            {
                metLedgerJournalTrans = LedgerJournalTrans::findJournalForVoucher(vendInvoiceJour.LedgerVoucher, vendInvoiceJour.InvoiceDate);
                VendInvoiceDocumentTmp.METHeaderNotes =  this.metGetDocuRef(metLedgerJournalTrans.ledgerJournaltable());
            }

            metHeaderNotes = VendInvoiceDocumentTmp.METHeaderNotes;
        }
        else
        {
            VendInvoiceDocumentTmp.METHeaderNotes = metHeaderNotes;
        }


    }

    /// <summary>
    /// Find notes related to reference table record.
    /// </summary>
    /// <param name = "_common">record buffer.</param>
    /// <returns>Notes</returns>
    public Notes metGetDocuRef(Common _common)
    {
        DocuRef     metDocuRef;
        select firstonly Notes from metDocuRef
            where metDocuRef.RefCompanyId  == _common.DataAreaId
                    && metDocuRef.RefTableId    == _common.TableId
                    && metDocuRef.RefRecId      == _common.RecId
                    && metDocuRef.TypeId        == METConstants::Note
                    && metDocuRef.Restriction   == DocuRestriction::External;

        return metDocuRef.Notes;
    }
